mapper.select:
SELECT bm.*, m.material_name, m.spec as specification, b.batch_no, w.node_name as warehouse_name FROM spd_bulk_material bm LEFT JOIN spd_material m ON bm.material_id = m.material_id LEFT JOIN spd_material_batch b ON bm.batch_id = b.batch_id LEFT JOIN spd_org_node w ON bm.warehouse_id = w.node_id WHERE bm.del_flag = #{delFlag}
AND bm.bulk_id = #{query.bulkId}
AND bm.material_id = #{query.materialId}
AND m.material_name LIKE CONCAT('%', #{query.materialName}, '%')
AND b.batch_no = #{query.batchNo}
AND bm.warehouse_id = #{query.warehouseId}
ORDER BY bm.create_time DESC
